import type { Exercise, ProgramTemplate, RawExercise, RawExerciseAr } from '@/types'
import rawExercises from './exercises.json'
import rawAr from './exercises.ar.json'
import rawPrograms from './programs.json'

/**
 * The bundled catalogue. The three JSON files are generated by `npm run catalog`
 * (scripts/build-catalog.mjs) — never edit them by hand.
 */
const ar = rawAr as unknown as RawExerciseAr

export const EXERCISES: Exercise[] = (rawExercises as unknown as RawExercise[]).map((e) => ({
  ...e,
  name: { en: e.name, ar: ar[e.id]?.name || e.name },
  steps: { en: e.steps, ar: ar[e.id]?.steps ?? [] },
}))

export const EXERCISE_BY_ID: ReadonlyMap<string, Exercise> = new Map(EXERCISES.map((e) => [e.id, e]))

export const PROGRAM_TEMPLATES = rawPrograms as unknown as ProgramTemplate[]

export const PROGRAM_TEMPLATE_BY_ID: ReadonlyMap<string, ProgramTemplate> = new Map(
  PROGRAM_TEMPLATES.map((p) => [p.id, p]),
)
